  pros: ['Works through fog, smoke and dust; unaffected by light', 'Single-chip radars are light, low-power and cheap', 'Very low compute (>100× real time on a NUC)', 'Autonomous UAV flights demonstrated (videos linked in README)'],
  cons: ['Velocity-only measurements: position drifts slowly without other aiding', 'Yaw aiding relies on Manhattan-world assumptions', 'Papers paywalled; numbers here are from the official README', 'ROS 1'],
  fails: { dark: 0, tex: 0, deg: 0, smoke: 0, spin: 1, vib: 1, dyn: 1, drift: 2 },
  failNotes: { dyn: 'RANSAC rejects movers unless they dominate the scan', drift: 'No absolute position or loop closure' },
  scores: { acc: 2, eff: 5, rob: 5, map: 1, glo: 1, rdy: 3 },
  drone: ['README links videos of autonomous UAV flights using ekf_rio / ekf_yrio and “autonomous radar inertial drone navigation even in dense fog” (x_rio).', 'Related: Kramer et al. ICRA 2020 flew a radar-inertial rig on a quadrotor in the dark; radar–inertial velocity error 0.14–0.17 m/s vs 0.31–0.56 m/s for VIO (Table II).'],
  setup: ['Start with a TI IWR6843AOP evaluation board and the provided launch files; calibrate radar–IMU extrinsics online.', 'Fuse its velocity into a larger graph alongside LiDAR/vision for best results.'],
  papers: [{ t: 'An EKF Based Approach to Radar Inertial Odometry', v: 'IEEE MFI 2020, pp. 152–159', links: [['DOI', doi('10.1109/MFI49285.2020.9235254')]] }, { t: 'x-RIO: Radar Inertial Odometry with Multiple Radar Sensors and Yaw Aiding', v: 'Gyroscopy and Navigation 12, 2021', links: [['DOI', doi('10.1134/S2075108721040039')]] }, { t: 'Radar-Inertial Ego-Velocity Estimation for Visually Degraded Environments (Kramer et al.)', v: 'IEEE ICRA 2020', links: [['DOI', doi('10.1109/ICRA40945.2020.9196666')], ['PDF', 'https://arpg.colorado.edu/papers/Kramer_ICRA_2020.pdf']] }],
  code: gh('christopherdoer/rio'), codeNote: 'GPL-3.0. Ego-velocity library: github.com/christopherdoer/reve.',
  req: { radar: true, imu: true }, cost: 1
